import{_ as d,o as r,c as o,a2 as s}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"02 · 物料清单","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/02-materials.md","filePath":"lab/shuangyu-fries/02-materials.md","lastUpdated":1786503105000}'),n={name:"lab/shuangyu-fries/02-materials.md"};function a(g,t,e,h,l,b){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="_02-·-物料清单" tabindex="-1">02 · 物料清单 <a class="header-anchor" href="#_02-·-物料清单" aria-label="Permalink to &quot;02 · 物料清单&quot;">​</a></h1><blockquote><p>阶段 1 · 提案 ｜ 2026-08-05 起 ｜ <strong>更新至 2026-08-09</strong> ｜ <strong>可直接发客户</strong></p></blockquote><blockquote><p>每一项都写了「缺了会怎样」。<strong>这不是客套，是让客户知道哪些东西卡着项目，他才会去找。</strong></p></blockquote><div class="tip custom-block"><p class="custom-block-title">「已收到的内容」这一列</p><p>记录贵司<strong>实际提供了什么</strong>，而不只是「给了 / 没给」。</p><p>用途有二：<strong>避免重复提供</strong>，以及在内容与需求不完全对应时（例如第 2 项）把差在哪里写清楚，而不是笼统标一个「已提供」就过去了。</p></div><h2 id="🔴-缺了做不完-必须有" tabindex="-1">🔴 缺了做不完（必须有） <a class="header-anchor" href="#🔴-缺了做不完-必须有" aria-label="Permalink to &quot;🔴 缺了做不完（必须有）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>物料</th><th>状态</th><th>已收到的内容</th><th>缺了会怎样</th></tr></thead><tbody><tr><td>1</td><td><strong>包装设计源文件</strong>（AI / PSD / 3D 工程文件，含刀版）</td><td>🟡 <strong>部分到位</strong></td><td><strong>印刷打样工程文件</strong>（2026-08-08）<br>· 含完整平面设计与扇形刀版展开图（415 外贴），分辨率足够提取素材<br>· <strong>非矢量源文件；「审核」栏空白，是否最终印刷版本待确认</strong><br>· 另有产品渲染图一张，<strong>商用授权待确认</strong><br>· 开盖视频（见第 7 项）补充了成品杯实物形态：银色卷边杯口、铝箔易揭盖，可作包装出镜合成参考</td><td>打样稿解决了素材提取与刀版确认，<strong>杯身弧面合成仍以矢量源文件为最稳</strong>。生成模型画不对中文和 logo，这一步<strong>没有捷径</strong></td></tr><tr><td>2</td><td><strong>VF 工艺的书面资料</strong>（工艺说明 / 技术方资料 / 参数）</td><td>🟡 <strong>部分到位</strong></td><td><strong>《VF 真空低温脱水技术》说明</strong>（文字，2026-08-06）<br>· 工艺原理：负压环境、热油传热、水分蒸发<br>· <strong>油温 80~90℃</strong><br>· <strong>疏松多孔结构</strong><br>· <strong>离心脱油工序</strong><br>· 成品五大特点（口感 / 原味 / 安全 / 食用方式 / 营养）</td><td>工艺原理已清楚。<strong>但该资料介绍的是 VF 技术在果蔬脆片上的通用应用，通篇未涉及本产品</strong>，尚不能作为片中表述的依据。补充项见下</td></tr><tr><td>3</td><td><strong>配料表与营养成分表</strong>（成品标签图即可）</td><td>🟡 <strong>已到位，版本待确认</strong></td><td><strong>印刷打样工程文件中含</strong>（2026-08-08，与第 1 项同源）<br>· 完整配料表（马铃薯≥50%、含番茄粉）<br>· 完整营养成分表、致敏物质提示、生产商与标准代号、保质期 9 个月<br>· <strong>打样稿≠成品标签，是否最终印刷版本待确认</strong></td><td>核对完成，结论见下文「配料表与营养成分表核对」。<strong>番茄相关表述有据；营养方向宣称几乎全部不可用</strong></td></tr></tbody></table><h3 id="关于第-2-项-·-追加四条-2026-08-06" tabindex="-1">关于第 2 项 · 追加四条（2026-08-06） <a class="header-anchor" href="#关于第-2-项-·-追加四条-2026-08-06" aria-label="Permalink to &quot;关于第 2 项 · 追加四条（2026-08-06）&quot;">​</a></h3><p>已收到的资料解决了「工艺原理」，以下四项决定「片中能说什么」：</p><table tabindex="0"><thead><tr><th>#</th><th>追加物料</th><th>状态</th><th>已收到的内容</th><th>为什么需要</th></tr></thead><tbody><tr><td>2a</td><td><strong>资料的出处</strong>——设备方 / 生产方 / 技术方 / 贵司自撰</td><td>⬜ 未提供</td><td>—</td><td>决定该资料能否作为广告表述的依据。<strong>技术方或生产方出具的文件可以，转述的介绍性材料不行</strong></td></tr><tr><td>2b</td><td><strong>本产品的实际工艺参数</strong>——油温是否即为 80~90℃</td><td>⬜ 未提供</td><td>—<br>（现有 80~90℃ 为<strong>技术通用范围</strong>）</td><td>若要将温度做成片中字幕，必须是本产品的实际参数</td></tr><tr><td>2c</td><td><strong>是否有脱油工序、脱油后含油量</strong></td><td>⬜ 未提供</td><td>—<br>（资料提及离心脱油，<strong>未确认本产品是否适用</strong>）</td><td><strong>这是我方最希望用在片中的一条</strong>，需确认本产品确有此工序</td></tr><tr><td>2d</td><td><strong>第三方检测报告</strong>（仅在贵司希望使用特定表述时需要）</td><td>⬜ 未提供</td><td>—</td><td>若希望片中出现「不含丙烯酰胺」「低脂」等表述，须有对应检测数据</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">第 1 项如果实在拿不到</p><p>退而求其次的顺序：<strong>设计源文件 &gt; 高清实拍多角度 &gt; 已有渲染图（需确认可商用）</strong>。</p><p>目前手上只有一张渲染图，且<strong>不知道是否有商用授权</strong>——这本身也要确认。</p></div><h2 id="🟡-缺了要绕路-强烈建议" tabindex="-1">🟡 缺了要绕路（强烈建议） <a class="header-anchor" href="#🟡-缺了要绕路-强烈建议" aria-label="Permalink to &quot;🟡 缺了要绕路（强烈建议）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>物料</th><th>状态</th><th>已收到的内容</th><th>缺了会怎样</th></tr></thead><tbody><tr><td>4</td><td><strong>产品实物 3–5 杯</strong>（打样件即可）</td><td>⬜ 未提供</td><td>开盖视频证实<strong>贵司有成品/打样件存货</strong>（见第 7 项），寄实物可行</td><td>撕封口那一镜可能实拍比生成快十倍。没实物就只能硬生成，废片率高、周期长。<strong>产品未上市，我方无法自行获取</strong>；开盖视频未拍内容物，实拍镜头仍须实物</td></tr><tr><td>5</td><td><strong>品牌 VI 规范</strong>（主色值、标准字、logo 使用规范）</td><td>🟡 <strong>部分到位</strong></td><td><strong>公司 logo 图一张</strong>（JPG，2134×1334，2026-08-09）<br>· 设计与打样稿一致（绿框、红底、白字），<strong>无 ® 标</strong>；白底、无透明通道、非矢量<br>· 屏幕色值可自该图取色；印刷专色值仍未知<br>· 仍缺：主色值书面值、标准字源、logo 使用规范</td><td>logo 本体可提取用于合成与片尾落版；但<strong>整体配色仍靠估</strong>（屏幕色≠印刷色），交付后被打回的风险只在程度减轻</td></tr><tr><td>6</td><td><s>日文元素的背景说明</s></td><td>✅ <strong>已定性</strong></td><td><strong>纯装饰性使用</strong>（口头）<br>与日本<strong>无</strong>技术、合作或出口关系</td><td>已按「无日本背景」确认执行：片中不出现日式场景、日文字幕、日式配乐。<strong>并由此新增一条包装出镜的执行约束，见下</strong></td></tr><tr><td>7</td><td><strong>既有素材</strong>：已拍过的照片、视频、详情页、竞品参考</td><td>🟡 <strong>一条</strong></td><td><strong>开盖视频一条</strong>（10 秒，1080×1920 竖屏，2026-08-08）<br>· 内容：成品杯置于桌面 → 双手展示包装 → 单手撕开铝箔易揭盖，一次完成<br>· 定位<strong>参考资料</strong>：确认杯型、封口方式与开盖动作路径；画面偏暗、有运动模糊，<strong>不可直接进成片</strong><br>· 细节：封口内侧沾有调味粉，实拍时应还原</td><td>该视频的价值在确认实物细节（卷边杯口、铝箔盖、揭盖手感），分镜「撕封口」一镜据此设计</td></tr><tr><td><strong>13</strong></td><td><strong>建议零售价</strong></td><td>⬜ 未提供</td><td>—</td><td>🆕 价格决定这支片子对着谁说话。<strong>同样一杯 46g，卖 5 元和卖 12 元是两种片子</strong>——货架上的对手不同，说服的重点也不同</td></tr><tr><td><strong>14</strong></td><td><strong>分销渠道</strong>——便利店 / 零食集合店 / 商超 / 纯电商，及各自占比</td><td>⬜ 未提供</td><td>—</td><td>🆕 决定片中的消费场景。若以纯电商为主，我方目前按线下即食场景所做的判断需整体调整</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">第 13、14 项为什么现在才提</p><p>2026-08-06 新增。原清单回答的都是「<strong>做这支片子需要什么</strong>」——源文件、工艺资料、实物、VI。</p><p>这两项回答的是另一个问题：「<strong>这支片子该拍什么</strong>」。</p><p>前者缺了做不出来，后者缺了做出来可能不对。<strong>后一种代价更高，因为它要到成片之后才暴露。</strong></p></div><div class="warning custom-block"><p class="custom-block-title">第 6 项定性后新增的一条执行约束</p><p>贵司已明确日文副标为装饰性使用、与日本无实质关联。据此，我方在片中不会出现任何日式元素——这一点原已写入提案。</p><p><strong>新增的一条是关于包装出镜镜头本身</strong>：包装上的日文属客观存在，出镜无需回避；但<strong>我方建议在镜头角度与景别上不刻意突出日文副标</strong>。</p><p>两点理由：</p><ol><li><strong>广告与包装的性质不同。</strong> 包装印制日文属行业常见做法；但广告中给日文特写、使其成为画面重点，可能被理解为对产品来源的暗示——在无实质关联的前提下，这一点需要避免。</li><li><strong>它对本品没有好处。</strong> 日文副标在没有日本背景支撑时，不构成任何品质背书，却会引导消费者联想到已有的日式同类产品。<strong>强调它，等于把注意力让给别人。</strong></li></ol><p>此条不影响物料需求，属分镜阶段的执行约定，先在此记录。</p></div><h2 id="🟢-影响判断-尽量提供" tabindex="-1">🟢 影响判断（尽量提供） <a class="header-anchor" href="#🟢-影响判断-尽量提供" aria-label="Permalink to &quot;🟢 影响判断（尽量提供）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>物料</th><th>状态</th><th>已收到的内容</th><th>用途</th></tr></thead><tbody><tr><td>8</td><td><strong>投放渠道与优先级</strong></td><td>🟡 已初步告知</td><td><strong>抖音短视频 + 电商详情页</strong>（口头）<br><strong>两者优先级未定</strong></td><td>仍需明确优先级——它决定先做哪一支、以及 A 片的开头能不能用一秒铺垫</td></tr><tr><td>9</td><td><strong>交期 / 预计上市时间</strong></td><td>🔴 <strong>升为必需</strong></td><td>—</td><td>产品未上市，<strong>广告交付须倒推自上市节点</strong>。物料齐备后我方需 6 个工作日（含 1 天合规审校），请据此告知期望上线日</td></tr><tr><td>10</td><td><s>预算范围</s></td><td>✅ <strong>已获知</strong></td><td>已获知<br>（<strong>具体内容不在本文档记录</strong>）</td><td>当前预算不构成创意与制作方式的约束，我方按提案原方案推进</td></tr><tr><td>11</td><td><s>产品是否已上市</s></td><td>✅ <strong>已确认</strong></td><td><strong>未上市，新品待发</strong>（口头）</td><td>相关物料已提升保密等级，见下方「保密与授权」</td></tr><tr><td>12</td><td><s>目标人群与竞品</s></td><td>🟡 <strong>已口头告知</strong></td><td>已口头提及<br><strong>具体说法待补入</strong></td><td><strong>建议以文字形式再确认一次</strong>，并与第 13、14 项一并提供——人群、价格、渠道三者要放在一起才判断得出调性。同样是薯条脆，打学生和打白领是两种片子</td></tr></tbody></table><h2 id="工艺资料的采用说明" tabindex="-1">工艺资料的采用说明 <a class="header-anchor" href="#工艺资料的采用说明" aria-label="Permalink to &quot;工艺资料的采用说明&quot;">​</a></h2><blockquote><p>2026-08-06 新增</p></blockquote><p>贵司提供的 VF 工艺资料已收到，内容详实，我方据此确定了片中四处工艺呈现，列在下方。</p><h3 id="我方计划采用的" tabindex="-1">我方计划采用的 <a class="header-anchor" href="#我方计划采用的" aria-label="Permalink to &quot;我方计划采用的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资料中的内容</th><th>片中如何呈现</th></tr></thead><tbody><tr><td>「形成疏松多孔结构」</td><td>作为<strong>断面镜头</strong>的内容依据——光能透过薯条脆的断面，是因为内部结构疏松多孔。这也是「脆」的物理原因</td></tr><tr><td>「油温恒定控制在 80~90℃」</td><td>可作为字幕出现的<strong>具体数字</strong>。它陈述事实，不作任何比较，风险低</td></tr><tr><td>「离心工艺去除表面多余油脂」</td><td>呈现为一道<strong>工序</strong>。这是我方最看重的一条——它正面回应了消费者对油炸零食的顾虑，且不需要任何检测数据支撑</td></tr><tr><td>「酥脆干爽，吃完无油腻感」</td><td>可作为口感描述使用。属感官表述，不属营养声称</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">第三条为什么重要</p><p>说「有一道脱油工序」和说「低脂」是性质完全不同的两句话。</p><p><strong>前者陈述的是生产环节，可查证；后者陈述的是营养结论，需检测数据达到国家标准的量化门槛。</strong></p><p>前者能达到的传播效果，其实不比后者差——观众看到离心机把油甩出去，得出的结论是他自己想的，比字幕告诉他的更可信。</p></div><h3 id="其余条目的处理" tabindex="-1">其余条目的处理 <a class="header-anchor" href="#其余条目的处理" aria-label="Permalink to &quot;其余条目的处理&quot;">​</a></h3><p>资料中涉及营养与含量的表述（低脂肪、低热量、高膳食纤维、富含维生素、保留钙铁、无添加等），<strong>须以本产品的配料表与营养成分表核对后</strong>，方能确定能否在片中使用——这类表述在国家标准中有明确的量化门槛。<strong>这也是第 3 项目前最急的原因。</strong></p><p>另有个别条目涉及食品广告的受限范畴，我方建议不纳入成片。若贵司希望使用其中某一条，请告知，我方会就该条单独说明所需材料与可行的替代表述。</p><h3 id="一处需要贵司确认的技术细节" tabindex="-1">一处需要贵司确认的技术细节 <a class="header-anchor" href="#一处需要贵司确认的技术细节" aria-label="Permalink to &quot;一处需要贵司确认的技术细节&quot;">​</a></h3><p>资料中「可泡水复水食用，复水后口感接近新鲜果蔬」一条，<strong>我方判断适用于苹果脆、秋葵脆等果蔬脆片，可能不适用于薯条脆</strong>。</p><p>这也是我方提出补充项 2a、2b 的原因——<strong>该资料介绍的是 VF 技术的通用应用，其中哪些条目适用于本产品，需要贵司确认。</strong></p><h2 id="配料表与营养成分表核对" tabindex="-1">配料表与营养成分表核对 <a class="header-anchor" href="#配料表与营养成分表核对" aria-label="Permalink to &quot;配料表与营养成分表核对&quot;">​</a></h2><blockquote><p>2026-08-08 新增</p></blockquote><p>贵司提供的印刷打样工程文件（番茄味薯条脆 202505 版，完稿 2025.6.4）中含完整配料表与营养成分表，物料清单中最急的一项至此闭环。逐条核对结论如下。</p><h3 id="打样稿转录" tabindex="-1">打样稿转录 <a class="header-anchor" href="#打样稿转录" aria-label="Permalink to &quot;打样稿转录&quot;">​</a></h3><p><strong>配料</strong>：马铃薯≥50%、棕榈油、番茄味复合调味料（白砂糖、番茄粉、麦芽糊精、白醋粉复合调味料、食用盐、味精、食用香精、食品添加剂（柠檬酸、二氧化硅、阿斯巴甜（含苯丙氨酸））、香辛料（辐照加工））。 <strong>致敏物质提示</strong>：可能含有大豆制品、麸质谷物制品、乳及乳制品、蛋类及其制品、甲壳纲类动物制品。</p><p><strong>营养成分表</strong>（每份 46 克）：</p><table tabindex="0"><thead><tr><th>项目</th><th>每份 46 克</th><th>营养素参考值%</th></tr></thead><tbody><tr><td>能量</td><td>1097 千焦</td><td>13%</td></tr><tr><td>蛋白质</td><td>3.0 克</td><td>5%</td></tr><tr><td>脂肪</td><td>17.0 克</td><td>28%</td></tr><tr><td>—饱和脂肪</td><td>7.5 克</td><td>38%</td></tr><tr><td>碳水化合物</td><td>24.5 克</td><td>8%</td></tr><tr><td>—糖</td><td>0 克</td><td>—</td></tr><tr><td>钠</td><td>92 毫克</td><td>5%</td></tr></tbody></table><p>表底注明：儿童青少年应避免过量摄入盐油糖。</p><h3 id="可以用的" tabindex="-1">可以用的 <a class="header-anchor" href="#可以用的" aria-label="Permalink to &quot;可以用的&quot;">​</a></h3><table tabindex="0"><thead><tr><th>表内内容</th><th>片中如何呈现</th></tr></thead><tbody><tr><td><strong>马铃薯≥50%</strong></td><td>🆕 硬依据，为主标题「原薯鲜切」提供配料表级别的支撑</td></tr><tr><td>配料含番茄粉</td><td>番茄相关表述有据，可作「番茄味来自番茄粉」一类说明</td></tr><tr><td>工艺类表述（断面 / 油温 / 脱油 / 口感）</td><td>不受本表影响，按上文「工艺资料的采用说明」执行</td></tr></tbody></table><h3 id="核对后不能用的" tabindex="-1">核对后不能用的 <a class="header-anchor" href="#核对后不能用的" aria-label="Permalink to &quot;核对后不能用的&quot;">​</a></h3><p>工艺资料中的营养与含量表述，按每 100 克折算、对照国标宣称门槛，<strong>均不可用</strong>：</p><table tabindex="0"><thead><tr><th>资料中的表述</th><th>实际数据（每 100 克）</th><th>宣称门槛</th><th>结论</th></tr></thead><tbody><tr><td>低脂肪</td><td>脂肪约 37 克</td><td>≤3 克</td><td>不可用，且属高值</td></tr><tr><td>低热量</td><td>约 2385 千焦</td><td>≤170 千焦</td><td>不可用</td></tr><tr><td>高膳食纤维 / 富含维生素 / 保留钙铁</td><td>表中未列</td><td>—</td><td>无依据</td></tr><tr><td>无添加</td><td>配料含食品添加剂</td><td>—</td><td>直接矛盾</td></tr><tr><td>低钠（资料未提，但易误踩）</td><td>约 200 毫克</td><td>≤120 毫克</td><td>不可用</td></tr></tbody></table><p><strong>关于「糖 0 克」</strong>：标示为 0 克，但配料含白砂糖与麦芽糊精，拿来做宣称存在合规与可信度风险，我方建议片中不碰。若贵司希望使用，请先告知该标注的依据。</p><div class="tip custom-block"><p class="custom-block-title">这张表反而把调性钉死了</p><p>「儿童青少年应避免过量摄入盐油糖」说明该产品的监管定位不是「健康替代品」。这不构成障碍——原提案的工艺路线本就不走营养方向——但提案与片中任何暗示「健康、低负担、吃了没负担」的措辞，应一律收掉。</p></div><h3 id="伴随收窄" tabindex="-1">伴随收窄 <a class="header-anchor" href="#伴随收窄" aria-label="Permalink to &quot;伴随收窄&quot;">​</a></h3><p>低脂、低热量既已被本表判死，追加项 2d（第三方检测报告）<strong>不再需要为「低脂 / 低卡」目的提供</strong>；仅当贵司希望使用其他量化宣称时才需要。</p><h3 id="仍待确认" tabindex="-1">仍待确认 <a class="header-anchor" href="#仍待确认" aria-label="Permalink to &quot;仍待确认&quot;">​</a></h3><p>本次到位的是<strong>打样稿</strong>（202505 版，完稿 2025.6.4，「审核」栏空白），非成品标签。以上转录是否为最终印刷版本的内容，须贵司确认。</p><h2 id="需要客户拍板的问题" tabindex="-1">需要客户拍板的问题 <a class="header-anchor" href="#需要客户拍板的问题" aria-label="Permalink to &quot;需要客户拍板的问题&quot;">​</a></h2><p>物料之外，这五个问题<strong>只有客户能回答</strong>：</p><table tabindex="0"><thead><tr><th>#</th><th>问题</th><th>我方建议</th></tr></thead><tbody><tr><td>1</td><td>主标题用「原薯鲜切」还是「VF 工艺」？</td><td><strong>建议鲜切做主、VF 做支撑</strong>，理由见提案 ①</td></tr><tr><td>2</td><td>日文元素有没有真实背景？</td><td>无书面依据则不碰</td></tr><tr><td>3</td><td>抖音与详情页，<strong>哪个先上</strong>？</td><td>已知两个渠道都要。<strong>建议先做 A 片（详情页），B 片从中剪出</strong>——反过来做要重拍</td></tr><tr><td>4</td><td>能否提供实物（含打样件）？</td><td><strong>必须由贵司提供。</strong> 产品未上市，我方无法自行获取。<strong>打样件即可</strong>，只要封口与包装形态与量产一致</td></tr><tr><td>5</td><td>是否接受「不做对比片」？</td><td><strong>必须接受</strong>——对比同类产品有法律风险，不是创意取舍</td></tr><tr><td>6</td><td>工艺资料中的受限表述，是否接受上节的处理方式？</td><td><strong>建议接受。</strong> 采用工序与温度的客观呈现，替代「不致癌」「低脂」类结论式表述</td></tr><tr><td>7</td><td>工艺资料中哪些条目确实适用于薯条脆？</td><td>需贵司逐条确认，尤其是「复水食用」一条</td></tr></tbody></table><h2 id="保密与授权" tabindex="-1">保密与授权 <a class="header-anchor" href="#保密与授权" aria-label="Permalink to &quot;保密与授权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>说明</th></tr></thead><tbody><tr><td>客户物料</td><td>仅存放于本工作区，不外传</td></tr><tr><td>渲染图商用授权</td><td><strong>待确认</strong>——这张图是谁做的、我方能否用于成片</td></tr><tr><td><strong>未上市信息</strong></td><td>✅ 已确认产品尚未上市。<strong>包装图、工艺资料、产品名与规格一律按机密处理</strong>，不进入任何对外可见的位置，直至贵司告知可公开的时间点</td></tr><tr><td>上市前的公开边界</td><td>请贵司明确：<strong>产品信息可对外披露的时间</strong>，以及成片是否需在上市日前保密</td></tr><tr><td><strong>保密约定</strong></td><td>双方尚未就保密范围形成书面约定。<strong>建议在本阶段补充</strong>，明确物料的使用范围、保存期限与销毁要求</td></tr><tr><td>成片版权与使用范围</td><td>需在合同中明确（投放渠道、时限、是否可用于我方作品集）</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">最后一条容易忘</p><p><strong>「是否可用于我方作品集」现在不谈，以后就没法谈了。</strong></p><p>这个项目的记录将来要脱敏写进<a href="/cases/">案例板块</a>，现在就把口子留出来。</p></div><hr><p><strong>上一步</strong> ← <a href="./01-proposal">01 · 提案</a> ｜ 客户反馈回来后写回 <a href="./00-brief">00 · Brief</a></p>',55)])])}const c=d(n,[["render",a]]);export{p as __pageData,c as default};
